        rc.object(self)
        try rc.arg(function, Rosetta.object(ArbitraryFunction.self))
        let slot1 = try rc.slot(coordinates, Rosetta.array(Rosetta.double))
        try rc.arg(lower, Rosetta.array(Rosetta.double))
        try rc.arg(upper, Rosetta.array(Rosetta.double))
        try rc.arg(surrogate, Rosetta.object(BayesianSurrogate.self))
        let reply = try rc.run()
        try reply.writeBack(slot1, &coordinates, Rosetta.array(Rosetta.double))
        return try reply.value(Rosetta.double)
    }

    /// The options this BayesianOptimization was configured with.
    ///
    /// Calls the C++ method `datamunge::optim::BayesianOptimization::options`.
    ///
    /// - Returns: The stored options.
    public func options() -> BayesianOptimizationOptions {
        return Rosetta.must {
