public func proportionTestOneSample(_ successes: Int, _ n: Int) throws -> HypothesisTestResult {
    var rc = Rosetta.Call(214)
    try rc.arg(successes, Rosetta.int)
    try rc.arg(n, Rosetta.int)
    return try rc.run().value(Rosetta.object(HypothesisTestResult.self))
}

